WITH unpacked AS (SELECT id, customer_id, created_at, items, ship_to, attributes, ARRAY_CONTAINS(coupon_codes, 'SPRING10') AS used_spring10, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts WHERE HOUR(created_at) BETWEEN 11 AND 19) SELECT customer_id, DATE_TRUNC('DAY', created_at) AS activity_day, MIN(created_at) AS started_at, MAX(created_at) AS ended_at, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes FROM unpacked GROUP BY 1, 2 HAVING (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 > 0;
